GAP = 150
pipe_x = 400
pipe_gap = 220
game_over = False
score = 0
scored = False


class Bird:
    def __init__(self):
        self.y = 300
        self.speed = 0

    def update(self):
        if key_pressed():
            self.speed = -8
        self.speed = self.speed + 0.5
        self.y = self.y + self.speed
        if self.y > 480:
            self.y = 480
            self.speed = 0

    def draw(self):
        draw_bird(100, self.y)


bird = Bird()


